#!/usr/bin/env python3
"""Apply predeclared human protocol using separate objective and listening evidence."""
import argparse,json,pathlib
p=argparse.ArgumentParser();p.add_argument('metrics',type=pathlib.Path);p.add_argument('listening',type=pathlib.Path);p.add_argument('output',type=pathlib.Path);a=p.parse_args();r=json.loads(a.metrics.read_text());h=json.loads(a.listening.read_text())
checks={'singleRecord':r['captureStarts']['microphone']==1,'noSyntheticNear':r['syntheticNearPcmNonzeroSamples']==0,'sdkNoExtraRecording':r['recordingAuditZero'],'rawOwnershipAndShutdown':r['rawOwnershipPass'],'senderGates':r['transportPass'],'receivedFarPlayback':r['receivedFarPass'],'noAbortOrErrors':not r['aborted'] and not r['errors'],'noNativeErrors':r['report']['captureStoppedStats'].get('dspErrors')==0 and r['report']['captureStoppedStats'].get('speakerError')=='' and not r['report']['captureStoppedStats'].get('renderTraceOverflow',True),'noClipping':r['rawClippedSamples']==r['outputClippedSamples']==0,'captureGapWithin100ms':r['maxAudioGapMs']<=100,'noReceiverTapDrops':r['receiverDroppedToDartMax']==0,'farOnlyCriterion':r['farOnlyCriterionPass'],'participantReceiverClarity':h['receiverClarityRange'][0]>=4,'participantNoMissingWords':h['receiverMissingWords']is False,'participantEchoTolerable':h['receiverEcho']in ('none','slight','none-to-slight'),'participantNearRecovery':h['nearRecoveryNormal']is True}
result={'kind':'physical-human-practicality-assessment','checks':checks,'limitedPracticalAcceptance':all(checks.values()),'scope':'One physical near participant at the normal microphone position, controller microphone + stereo speaker, RAW record, baseline standalone AEC, local WebRTC receiver, recorded far fixture. Camera remains synthetic. Short prompted reading only.','dtEchoMetric':'Inconclusive for source separation; real-near clean reference absent. DT spectral diagnostics do not establish near preservation.','notEstablished':['second live conversation partner','independent second listener','other microphones','physical Windows camera','Bluetooth','long sessions','other operating systems'],'metrics':a.metrics.name,'listening':a.listening.name};a.output.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
